import org.junit.jupiter.api.Test;                 // Jupiter API
import static org.junit.jupiter.api.Assertions.*;  // static assertions

class CalculatorTest {              // no 'public' needed in JUnit 5
    @Test
    void shouldAddTwoNumbers() {
        // Arrange
        var calc = new Calculator();
        // Act
        int result = calc.add(2, 3);
        // Assert
        assertEquals(5, result, "2 + 3 should be 5"); // expected, actual, message
    }
}
```
Note the imports come from `org.junit.jupiter.api` — that's the JUnit 5 package, not JUnit 4's `org.junit`.

