import static org.junit.jupiter.api.Assertions.*;

@Test
void coreAssertions() {
    assertEquals(5, calc.add(2, 3));          // expected first
    assertTrue(calc.add(2, 3) > 0);
    assertNotNull(repo.findById(1L));

    // assertThrows returns the thrown exception for further checks
    var ex = assertThrows(IllegalArgumentException.class,
                          () -> calc.divide(1, 0));
    assertEquals("divisor must not be zero", ex.getMessage());

    // assertAll reports ALL failures, not just the first
    var p = new Point(2, 3);
    assertAll("point",
        () -> assertEquals(2, p.x()),
        () -> assertEquals(3, p.y()));
}
