import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;

// @ValueSource: one argument per run
@ParameterizedTest
@ValueSource(ints = {2, 4, 100, -8})
void evenNumbersAreEven(int n) {
    assertTrue(n % 2 == 0);
}

// @CsvSource: input -> expected pairs
@ParameterizedTest(name = "{0} chars -> valid={1}")
@CsvSource({"abc, false", "abcd1234, true", "'', false"})
void validatesPasswordLength(String pw, boolean expected) {
    assertEquals(expected, validator.isValid(pw));
}

// @MethodSource: complex objects
@ParameterizedTest
@MethodSource("orders")
void pricesOrders(Order order, double expected) {
    assertEquals(expected, service.price(order));
}
static Stream<Arguments> orders() {
    return Stream.of(Arguments.of(new Order(100.0, PREMIUM), 90.0),
                     Arguments.of(new Order(100.0, REGULAR), 100.0));
}
