class BankAccountTest {
    BankAccount account;
    @BeforeEach void createAccount() { account = new BankAccount(); } // runs first

    @Nested
    @DisplayName("when the account is empty")
    class WhenEmpty {
        @Test void balanceIsZero() { assertEquals(0, account.balance()); }
        @Test void withdrawThrows() {
            assertThrows(InsufficientFundsException.class, () -> account.withdraw(10));
        }
    }

    @Nested
    @DisplayName("when the account has 100")
    class WhenFunded {
        @BeforeEach void deposit() { account.deposit(100); } // runs AFTER createAccount
        @Test void canWithdrawWithinBalance() {
            account.withdraw(40);
            assertEquals(60, account.balance());
        }
    }
}
